node -e "
const fs = require('fs');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#') && line.includes('=')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('=');
    envVars[key] = value;
  }
});

// Prepare JSON payload
const jsonData = JSON.stringify(envVars, null, 2);
console.log('Sending environment variables:', jsonData);

// POST to the endpoint
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonData)
  }
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });
  res.on('end', () => {
    console.log('Response status:', res.statusCode);
    console.log('Response body:', data);
  });
});

req.on('error', (error) => {
  console.error('Error:', error.message);
  console.error('The server at localhost:47301 may not be running');
});

req.write(jsonData);
req.end();
"

